(function(){let serial=0;function render(item){if(item?.props?.scenario!=='phys.5.frontier.rotation')return null;const root=document.createElement('section');root.className='card physics-rotation-lab';const uid='rotation-'+(++serial),RotationCore=window.RotationCore,RotationDensity=window.RotationDensity;let disposed=false,mounted=false;const disposers=[];root.innerHTML="<h3>What sets a galaxy\u2019s circular speed?</h3><p>Ideal circular orbits in a stationary, axisymmetric disk plus a spherical halo. This is a hypothetical model, not measured galaxy data.</p><div data-rotation-role=\"controls\"></div><button data-rotation-role=\"reset\">Reset</button> <button data-rotation-role=\"degeneracy\">Compare equal curves, different thickness</button><p data-rotation-role=\"degeneracy-note\" role=\"status\"></p><p>Gold: stellar disk \u00b7 Blue: halo \u00b7 White: combined circular speed \u00b7 Purple points: fixed synthetic sample with \u00b11\u03c3 bars.</p><div class=\"plot-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Rotation plot; scroll horizontally on narrow screens\"><svg data-rotation-role=\"plot\" viewBox=\"0 0 800 440\" role=\"img\" aria-label=\"Circular speed in kilometres per second against radius in kiloparsecs\"></svg></div><p>On a narrow screen, scroll the plot sideways to inspect its full calibrated range.</p><p data-rotation-role=\"readout\" aria-live=\"polite\"></p><h2>Disk density in three dimensions</h2><p>Surface at 10% of the current central disk density. It is a density contour, not the edge of the disk. Equal scale on every axis; rotation changes only the view. The orthographic scale bar measures distances parallel to the view plane.</p><button data-rotation-role=\"turn\">Rotate view</button> <button data-rotation-role=\"tilt\">Tilt view</button> <button data-rotation-role=\"camera-reset\">Reset view</button><div style=\"position:relative\"><svg data-rotation-role=\"model-scale\" viewBox=\"0 0 800 440\" aria-label=\"Physical scale for the 3D view\" style=\"position:absolute;inset:0;min-width:0;pointer-events:none;background:none;z-index:1\"></svg><canvas data-rotation-role=\"density-model\" width=\"800\" height=\"440\" style=\"width:100%;height:auto\" aria-label=\"Rotatable disk constant-density surface\"></canvas></div><p data-rotation-role=\"density-status\" role=\"status\"></p><p>The comparison sample is generated from one fixed disk/halo model with a reproducible pseudo-random Gaussian noise realization (\u03c3 = 8 km/s at each radius). It stays fixed as you change the model. Error bars are one assumed standard deviation, not confidence intervals for fitted masses. The mismatch is \u03a3[(sample \u2212 model)/\u03c3]\u00b2; no p-value or unique physical conclusion is inferred.</p><p>The disk uses a Miyamoto\u2013Nagai potential; its midplane force cannot be calculated by treating its mass as spherical. The halo follows an NFW density profile. Halo scale mass is 4\u03c0\u03c1\u209br\u209b\u00b3, not total or virial mass. The untruncated halo\u2019s total mass diverges; this view covers only 0\u201340 kpc. Bars, spiral structure, gas pressure and non-circular motions are omitted. A rotation curve alone does not uniquely establish dark-matter physics.</p>";const get=key=>root.querySelector('[data-rotation-role="'+key+'"]');
const sampleData=RotationCore.comparison();const defaults={diskMass:6e10,diskA:3,diskB:.3,haloScaleMass:8e11,haloRadius:20,radius:8},state={...defaults},controls=[['diskMass','Disk mass (10¹⁰ solar masses)',0,15,.5,1e10],['diskA','Disk radial scale a (kpc)',0,10,.25,1],['diskB','Disk vertical scale b (kpc)',.1,2,.1,1],['haloScaleMass','Halo scale mass (10¹¹ solar masses)',0,20,.5,1e11],['haloRadius','Halo scale radius (kpc)',5,50,1,1],['radius','Inspect radius (kpc)',0,40,.25,1]],NS='http://www.w3.org/2000/svg',plot=get('plot');
function node(tag,attrs,text){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;plot.append(e);return e;}
for(const[key,title,min,max,step,gain]of controls){const label=document.createElement('label');label.textContent=title+' ';const input=document.createElement('input');Object.assign(input,{id:uid+'-'+key,type:'number',min,max,step,value:state[key]/gain});input.setAttribute('aria-label',title);input.onchange=()=>{const value=input.valueAsNumber;if(!Number.isFinite(value)||value<min||value>max){input.value=state[key]/gain;return;}state[key]=value*gain;render();};input.dataset.rotationRole=key;label.append(input);get('controls').append(label);}
function render(){const rows=Array.from({length:161},(_,i)=>RotationCore.model(i/4,state)),maximum=Math.max(50,Math.ceil(Math.max(...rows.map(r=>r.totalSpeedKms),RotationCore.model(state.radius,state).totalSpeedKms,...sampleData.map(d=>d.speedKms+d.sigmaKms))/50)*50),X=r=>70+660*r/40,Y=v=>370-320*v/maximum;plot.replaceChildren();for(let i=0;i<=4;i++){const radius=i*10,y=maximum*i/4;node('line',{x1:70,y1:Y(y),x2:730,y2:Y(y),stroke:'#34435b'});node('text',{x:60,y:Y(y)+5,'text-anchor':'end'},String(Number(y.toFixed(2))));node('text',{x:X(radius),y:395,'text-anchor':'middle'},radius);}node('text',{x:400,y:425,'text-anchor':'middle'},'Radius (kpc)');node('text',{x:15,y:210,transform:'rotate(-90 15 210)','text-anchor':'middle'},'Circular speed (km/s)');for(const[key,color]of [['diskSpeedKms','#f4c35b'],['haloSpeedKms','#60b5ff'],['totalSpeedKms','#ffffff']]){const p=node('polyline',{points:rows.map(r=>X(r.radiusKpc)+','+Y(r[key])).join(' '),fill:'none',stroke:color,'stroke-width':3,'data-component':key});p.dataset.values=JSON.stringify(rows.map(r=>[r.radiusKpc,r[key]]));}const current=RotationCore.model(state.radius,state);node('line',{x1:X(state.radius),x2:X(state.radius),y1:50,y2:370,stroke:'#c0c8d8','stroke-dasharray':'4 4'});node('circle',{cx:X(state.radius),cy:Y(current.totalSpeedKms),r:5,fill:'#ffffff'});get('readout').textContent=`At ${state.radius} kpc: disk ${current.diskSpeedKms.toFixed(2)} km/s; halo ${current.haloSpeedKms.toFixed(2)} km/s; combined ${current.totalSpeedKms.toFixed(2)} km/s. Enclosed halo mass ${(current.haloEnclosedMassSolar/1e10).toFixed(3)} × 10¹⁰ solar masses. Squared component speeds add.`;let weightedMismatch=0;for(const d of sampleData){const predicted=RotationCore.model(d.radiusKpc,state).totalSpeedKms;weightedMismatch+=((d.speedKms-predicted)/d.sigmaKms)**2;node('line',{x1:X(d.radiusKpc),x2:X(d.radiusKpc),y1:Y(d.speedKms-d.sigmaKms),y2:Y(d.speedKms+d.sigmaKms),stroke:'#e58af6','stroke-width':2,'data-comparison-error':d.radiusKpc});node('circle',{cx:X(d.radiusKpc),cy:Y(d.speedKms),r:3,fill:'#e58af6','data-synthetic-observation':d.radiusKpc});}get('readout').textContent+=` Weighted squared mismatch to the fixed synthetic sample: ${weightedMismatch.toFixed(3)} (dimensionless).`;root.rotationReview={comparison:sampleData,weightedMismatch,state:{...state},rows,current,maximum,plot:{left:70,width:660,bottom:370,height:320}};}
get('reset').onclick=()=>{Object.assign(state,defaults);for(const[key,,, , ,gain]of controls)get(key).value=state[key]/gain;render();};render();
let thickComparison=false;
get('degeneracy').onclick=()=>{thickComparison=!thickComparison;Object.assign(state,defaults,thickComparison?{diskA:2.3,diskB:1}:{});for(const[key,,,,,gain]of controls)get(key).value=state[key]/gain;render();get('degeneracy-note').textContent=thickComparison?'Thicker disk: a = 2.3 kpc, b = 1 kpc. The comparison restores the fixed reference masses and halo. Its midplane rotation curve is exactly the same as a = 3 kpc, b = 0.3 kpc because a+b is unchanged. The three-dimensional mass density differs.':'Thinner reference disk: a = 3 kpc, b = 0.3 kpc. Both comparison states share a+b = 3.3 kpc and the same midplane rotation curve.';};
const originalReset=get('reset').onclick;get('reset').onclick=()=>{thickComparison=false;get('degeneracy-note').textContent='';originalReset();};
for(const[key]of controls){const input=get(key),original=input.onchange;input.onchange=()=>{original();get('degeneracy-note').textContent='';};}

(()=>{'use strict';const canvas=get('density-model'),status=get('density-status'),gl=canvas.getContext('webgl2');let yaw=.4,pitch=.5,buffer,count=0,radius=1,positions,program;
if(!gl){status.textContent='3D rendering unavailable in this browser. The calibrated rotation plot remains available.';return;}
function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;}
function setup(){program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,`#version 300 es
in vec3 position;uniform float yaw,pitch,radius,aspect;out vec3 world;void main(){world=position;float a=cos(yaw),b=sin(yaw),c=cos(pitch),d=sin(pitch);vec3 q=vec3(a*position.x-b*position.y,b*position.x+a*position.y,position.z);vec3 v=vec3(q.x,c*q.z-d*q.y,d*q.z+c*q.y);gl_Position=vec4(v.x/(radius*aspect),v.y/radius,-v.z/(4.0*radius),1.0);}`));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,`#version 300 es
precision highp float;in vec3 world;out vec4 color;void main(){vec3 n=normalize(cross(dFdx(world),dFdy(world)));float light=.3+.7*abs(dot(n,normalize(vec3(.3,-.5,1.0))));color=vec4(vec3(.94,.68,.25)*light,1.0);}`));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));for(const shader of gl.getAttachedShaders(program))gl.deleteShader(shader);buffer=gl.createBuffer();gl.enable(gl.DEPTH_TEST);gl.disable(gl.CULL_FACE);}
function draw(){if(disposed||gl.isContextLost())return;const width=Math.max(1,Math.round(canvas.clientWidth*devicePixelRatio)),height=Math.round(width*.55);canvas.width=width;canvas.height=height;gl.viewport(0,0,width,height);gl.clearColor(.06,.09,.14,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(program);gl.bindBuffer(gl.ARRAY_BUFFER,buffer);const a=gl.getAttribLocation(program,'position');gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,3,gl.FLOAT,false,0,0);for(const[k,v]of Object.entries({yaw,pitch,radius,aspect:width/height}))gl.uniform1f(gl.getUniformLocation(program,k),v);gl.drawArrays(gl.TRIANGLES,0,count);const overlay=get('model-scale'),ns='http://www.w3.org/2000/svg';overlay.replaceChildren();const aspect=width/height,desired=radius*aspect*.4,power=10**Math.floor(Math.log10(desired)),length=[1,2,5,10].map(v=>v*power).filter(v=>v<=desired).at(-1)||power,pixels=length/(2*radius*aspect)*800;function mark(tag,attrs,text){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text)e.textContent=text;overlay.append(e);}mark('line',{x1:40,x2:40+pixels,y1:400,y2:400,stroke:'#ffffff','stroke-width':3});mark('text',{x:40,y:385,style:'font:28px system-ui'},length.toPrecision(2)+' kpc');overlay.dataset.scale=JSON.stringify({lengthKpc:length,x1:40,x2:40+pixels,viewWidth:800,radius,aspect});canvas.dataset.ready='true';}
function update(){if(disposed)return;try{const s=root.rotationReview.state,m=RotationDensity.densitySurface(s,.1,128,128);positions=new Float32Array(m.triangles.flatMap(t=>t.flatMap(i=>m.positions[i])));count=positions.length/3;radius=Math.max(.1,...m.positions.map(p=>Math.hypot(...p)))*1.1;gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,positions,gl.STATIC_DRAW);status.textContent=m.empty?'Zero disk mass: no disk density surface.':`Density ${m.density.toPrecision(5)} solar masses/kpc³. Maximum source radius ${(radius/1.1).toPrecision(4)} kpc. The halo is not drawn.`;root.rotationMeshReview={gl,positions,mesh:m,state:{...s},get radius(){return radius;},get program(){return program;}};draw();}catch(e){delete canvas.dataset.ready;status.textContent='Density model unavailable: '+e.message;}}
get('turn').onclick=()=>{yaw+=.3;draw();};get('tilt').onclick=()=>{pitch+=.25;draw();};get('camera-reset').onclick=()=>{yaw=.4;pitch=.5;draw();};for(const input of root.querySelectorAll('[data-rotation-role="controls"] input'))input.addEventListener('change',update);for(const id of ['reset','degeneracy'])get(id).addEventListener('click',update);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();delete canvas.dataset.ready;status.textContent='3D context lost; waiting for recovery.';});canvas.addEventListener('webglcontextrestored',()=>{setup();update();});const resizeObserver=new ResizeObserver(draw);resizeObserver.observe(canvas);disposers.push(()=>resizeObserver.disconnect());disposers.push(()=>{if(!gl.isContextLost()){gl.useProgram(null);gl.bindBuffer(gl.ARRAY_BUFFER,null);gl.deleteBuffer(buffer);gl.deleteProgram(program);}});try{setup();update();}catch(e){status.textContent=e.message;}})();

root.dispose=()=>{if(disposed)return;disposed=true;for(const dispose of disposers)dispose();root.dataset.disposed='true';};const lifecycle=new MutationObserver(()=>{if(root.isConnected)mounted=true;else if(mounted)root.dispose();});lifecycle.observe(document,{childList:true,subtree:true});disposers.push(()=>lifecycle.disconnect());return root;}window.PrimerRotationLab={render};})();
